input.command:
cd /workspace && for f in $(git diff --name-only origin/main...HEAD -- 'app/assets/stylesheets/desktop/*' 'app/assets/stylesheets/mobile/*'); do
  git diff origin/main...HEAD -- "$f" | grep -B3 -E "^\+.*dark-light-choose\(scale-color\(\\\$primary, \\\$lightness: (70|30|50)%\)" | grep -E "^\-.*lightness: (30|70|20)%" -A3 | true
done
echo "---"
git diff origin/main...HEAD -- app/assets/stylesheets | grep -E "^(diff --git|@@|\-.*lightness|\+.*lightness)" | awk '
/^diff --git/{file=$0}
/^@@/{hunk=$0}
/^-.*lightness/{prev=$0; prevfile=file; prevhunk=hunk}
/^\+.*lightness/{ 
  match(prev, /lightness: [0-9]+%/); old=substr(prev,RSTART,RLENGTH);
  match($0, /scale-color\(\$primary, \$lightness: [0-9]+%/); new=substr($0,RSTART,RLENGTH);
  print prevfile" "prevhunk; print "  OLD:"prev; print "  NEW:"$0
}'

